package com.pulsefit.apigateway; import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import org.springframework.stereotype.Component; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; @Component public class JwtService {private static final String SECRET="PulseFit-College-Demo-Secret-Key-2026-ChangeMe-At-Least-32";private SecretKey key(){return Keys.hmacShaKeyFor(SECRET.getBytes(StandardCharsets.UTF_8));}public boolean valid(String token){try{Jwts.parser().verifyWith(key()).build().parseSignedClaims(token);return true;}catch(Exception e){return false;}}}
